\begin{theorem}
Let $k\geq 3$ be a natural number, and let $G$ be a graph with $\Delta(G)\leq k$ not containing a clique on $k+1$ vertices. Suppose that $L(v)$ is an arbitrary list assignment, with $\lvert L(v)\rvert =k$. Let $F$ be an arbitrary constraint graph for $(L,G)$. Then there is a list coloring of $G$ respecting $F$.
\end{theorem}
